import{_ as i,a8 as o,o as n,c as s,ah as t,K as a}from"./chunks/framework.D31WLDJp.js";import"./chunks/theme.CP9whvzN.js";const k=JSON.parse('{"title":"记忆库引入 journal 流水层","description":"","frontmatter":{"type":"decision","scope":"global","created":"2026-09-12T00:00:00.000Z","updated":"2026-09-12T00:00:00.000Z","tags":["memory-system","journal","工作流"]},"headers":[],"relativePath":"vault/Memory/Decisions/记忆库引入journal流水层.md","filePath":"vault/Memory/Decisions/记忆库引入journal流水层.md","lastUpdated":1789374053000}'),d={name:"vault/Memory/Decisions/记忆库引入journal流水层.md"};function c(u,e,_,m,h,b){const r=o("NolebaseGitContributors"),l=o("NolebaseGitChangelog");return n(),s("div",null,[e[0]||(e[0]=t('<h1 id="记忆库引入-journal-流水层" tabindex="-1">记忆库引入 journal 流水层 <a class="header-anchor" href="#记忆库引入-journal-流水层" aria-label="Permalink to “记忆库引入 journal 流水层”">​</a></h1><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>workbuddy 类工具的记忆采用「MEMORY.md(长期) + 日期.md(每日流水)」两层形式(实例见 <code>E:\\Projects\\work\\qiye-beidiao\\.workbuddy\\memory</code>)。评估该形式是否引入本记忆库。</p><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to “决策”">​</a></h2><p><strong>拒绝按日期分文件</strong>;引入<strong>每项目单文件流水层</strong> <code>Projects\\&lt;项目名&gt;\\working\\journal.md</code>,已写入 Rule(读取/写入规则 3/会话收尾 ①②)。</p><h2 id="理由" tabindex="-1">理由 <a class="header-anchor" href="#理由" aria-label="Permalink to “理由”">​</a></h2><ul><li>日期文件按时间而非主题组织,同一主题被打散在多天、只能按日期检索、无限增长永不回收,与 Rule「原地动态更新,不散建笔记」冲突。</li><li>workbuddy 用日期文件是因为它没有外部人工维护的库,流水即其唯一记忆;本库已有主题层(Lessons/Decisions 等),日期文件功能重复且更差。</li><li>单文件时间线保留低成本追加(先粗记后蒸馏)和时间线叙事价值,且永远可全文检索。</li><li>命名用 <code>journal.md</code> 而非 <code>MEMORY.md</code>:后者是各 AI 工具私有记忆的通用文件名,Rule 禁止记忆写入工具私有位置,同名易被误改写。</li></ul><h2 id="机制要点" tabindex="-1">机制要点 <a class="header-anchor" href="#机制要点" aria-label="Permalink to “机制要点”">​</a></h2><ol><li>journal 是<strong>暂存层不是记忆本体</strong>:当日粗记,有长期价值的条目标「候选」。</li><li>会话收尾时「候选」条目按写入规则蒸馏到最终位置(Preferences/Plans/Decisions/Lessons/Workflows/Projects 主题笔记)并登记 Inbox,原文留痕。</li><li>超过约 500 行时,旧段压缩为「阶段小结」小节(只留结论 + wikilink 指向已转正笔记),防文件膨胀拖慢 Obsidian。</li><li>存量教训迁移提示:qiye-beidiao workbuddy 记忆中 23 条背调方法论(多壳识别/参保人数信号/JD 穿越条目等)尚未沉淀进本库,候选迁入 <code>Lessons\\</code> 与 <code>Projects\\work\\</code>。</li></ol>',9)),a(r),a(l)])}const f=i(d,[["render",c]]);export{k as __pageData,f as default};
